import pandas as pd

def clean(df):
    df = df.copy()
    # Normalize text columns (strip whitespace)
    for col in ["Category", "Region"]:
        if col in df.columns:
            df[col] = df[col].where(df[col].isna(), df[col].astype(str).str.strip())
    # Normalize Region case variants: title case (west->West, north->North, etc.)
    if "Region" in df.columns:
        df["Region"] = df["Region"].where(df["Region"].isna(), df["Region"].astype(str).str.title())
    # Clean Date to ISO YYYY-MM-DD, invalid become NaT
    if "Date" in df.columns:
        df["Date"] = pd.to_datetime(df["Date"], errors="coerce")
    # Ensure numeric types
    for col in ["Quantity", "Price", "Revenue"]:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors="coerce")
    # Quantity must be >=1 (positive whole number) - drop invalid rows
    if "Quantity" in df.columns:
        df = df[df["Quantity"] >= 1]
        # also drop NaN quantities
        df = df.dropna(subset=["Quantity"])
    # Price min 0
    if "Price" in df.columns:
        df = df[df["Price"] >= 0]
    # Recalculate Revenue = Quantity * Price (cross-column fix)
    if "Quantity" in df.columns and "Price" in df.columns:
        df["Revenue"] = df["Quantity"] * df["Price"]
    return df

def answer(df):
    # group by Category total revenue
    allowed = ["Electronics", "Accessories", "Furniture", "Office Supplies"]
    if "Category" in df.columns:
        df["Category"] = df["Category"].astype(str).str.strip()
        df = df.dropna(subset=["Category"])
        df = df[df["Category"].isin(allowed)]
    grouped = df.groupby("Category")["Revenue"].sum()
    result = {str(k): float(v) for k, v in grouped.items() if pd.notna(k)}
    return result
